  @media (max-width:430px){
    body{padding:8px}
    header,section{padding:12px}
    h1{font-size:1.22rem}
    .preview-title{font-size:1.22rem}
    button{font-size:.84rem;padding:8px 10px}
    .top-actions,.button-row,.chips{gap:6px}
  }

  @media print{
    body{background:white;padding:0}
    header,.input-panel,.button-row,.top-actions{display:none}
    main{display:block}
    section{box-shadow:none;border:0}
  }
</style>
</head>
<body>
<div class="app">
  <header>
    <h1>Ecommerce Shelf Card Stress Test</h1>
    <p class="sub">Enter product details, pressure-test the claims, preview the card, generate SEO snippets, and export copy. Works offline with no libraries, APIs, fonts, or external assets.</p>
    <div class="top-actions">
      <button type="button" class="primary" id="sampleBtn">Load sample</button>
      <button type="button" id="clearBtn">Clear</button>
      <button type="button" id="printBtn">Print</button>
    </div>
  </header>

  <main>
    <section class="input-panel">
      <h2>Product inputs</h2>

      <div class="two">
        <div class="field">
          <label for="brand">Brand</label>
          <input id="brand" autocomplete="off" placeholder="Example: Northline">
        </div>
        <div class="field">
          <label for="product">Product name</label>
          <input id="product" autocomplete="off" placeholder="Example: Trail Mug 20 oz">
        </div>
      </div>

      <div class="two">
        <div class="field">
          <label for="category">Category</label>
          <input id="category" autocomplete="off" placeholder="Example: insulated travel mug">
        </div>
        <div class="field">
          <label for="keyword">Target keyword</label>
          <input id="keyword" autocomplete="off" placeholder="Example: leakproof travel mug">
        </div>
      </div>

      <div class="two">
        <div class="field">
          <label for="audience">Primary shopper</label>
          <input id="audience" autocomplete="off" placeholder="Example: commuters, campers, gift buyers">
        </div>
        <div class="field">
          <label for="price">Price / offer</label>
          <input id="price" autocomplete="off" placeholder="Example: $29.99, free shipping over $50">
        </div>
      </div>

      <div class="field">
        <label for="features">Features and specs</label>
        <textarea id="features" placeholder="One per line. Example:
20 oz capacity
Keeps drinks hot up to 8 hours
Fits standard cup holders
Dishwasher-safe lid"></textarea>
        <div class="hint">Use concrete specs. The preview uses the first few as shelf-card bullets.</div>
      </div>

      <div class="field">
        <label for="claims">Marketing claims to stress-test</label>
        <textarea id="claims" placeholder="One per line. Example:
The best mug for commuters
Leakproof lid
Eco-friendly stainless steel
Keeps coffee hot all morning"></textarea>
      </div>

      <div class="field">
        <label for="evidence">Evidence, proof, or support</label>
        <textarea id="evidence" placeholder="One per line. Example:
Tested upside down for 2 minutes with no visible leaks
18/8 stainless steel body
Average rating 4.7 from 420 reviews"></textarea>
      </div>

      <div class="field">
        <label for="objections">Known objections / risk notes</label>
        <textarea id="objections" placeholder="Example:
May not fit oversized car cup holders
Not for carbonated drinks
Color may vary slightly by screen"></textarea>
      </div>

      <div class="two">
        <div class="field">
          <label for="tone">Tone</label>
          <select id="tone">
            <option value="clear">Clear and practical</option>
            <option value="premium">Premium</option>
            <option value="warm">Warm giftable</option>
            <option value="technical">Technical</option>
            <option value="minimal">Minimal</option>
          </select>
        </div>
        <div class="field">
          <label for="cta">CTA</label>
          <input id="cta" autocomplete="off" placeholder="Example: Add to cart" value="Add to cart">
        </div>
      </div>
    </section>

    <div class="sticky">
      <section>
        <h2>Live shelf card preview</h2>
        <article class="shelf-card" aria-live="polite">
          <div class="badge" id="previewBadge">Category</div>
          <h3 class="preview-title" id="previewTitle">Product name goes here</h3>
          <p class="preview-desc" id="previewDesc">Add product details to generate a tighter shelf-card description.</p>
          <ul class="preview-list" id="previewBullets"></ul>
          <div class="price-line">
            <span class="price" id="previewPrice">$0.00</span>
            <span class="small-pill" id="previewProof">Proof needed</span>
          </div>
          <span class="cta" id="previewCta">Add to cart</span>
        </article>

        <div class="score-row">
          <div class="score-box">
            <div class="score-label">Shelf strength</div>
            <div class="meter"><span id="shelfMeter"></span></div>
            <div class="score-num" id="shelfScore">0 / 100</div>
          </div>
          <div class="score-box">
            <div class="score-label">Evidence strength</div>
            <div class="meter"><span id="proofMeter"></span></div>
            <div class="score-num" id="proofScore">0 / 100</div>
          </div>
          <div class="score-box">
            <div class="score-label">Claim risk</div>
            <div class="meter"><span id="riskMeter"></span></div>
            <div class="score-num" id="riskScore">0 / 100</div>
          </div>
        </div>
      </section>

      <section style="margin-top:12px">
        <h2>Claim and evidence warnings</h2>
        <div id="warnings" class="warning-list"></div>
      </section>
    </div>

    <section>
      <h2>SEO title, H1, and meta</h2>
      <div class="seo-box">
        <div class="snippet">
          <label>SEO title</label>
          <div class="snippet-title" id="seoTitle"></div>
          <div class="count" id="seoTitleCount"></div>
        </div>

        <div class="snippet">
          <label>H1</label>
          <div id="seoH1"></div>
          <div class="count" id="seoH1Count"></div>
        </div>

        <div class="snippet">
          <label>Meta description</label>
          <div class="snippet-meta" id="seoMeta"></div>
          <div class="count" id="seoMetaCount"></div>
        </div>

        <div class="snippet">
          <label>Search result preview</label>
          <div class="snippet-title" id="serpTitle"></div>
          <div class="snippet-url" id="serpUrl"></div>
          <div class="snippet-meta" id="serpMeta"></div>
        </div>
      </div>
    </section>

    <section>
      <h2>Exportable copy</h2>
      <textarea id="exportText" class="export-area" readonly></textarea>
      <div class="button-row" style="margin-top:10px">
        <button type="button" class="primary" id="copyBtn">Copy copy</button>
        <button type="button" id="copySeoBtn">Copy SEO only</button>
        <button type="button" id="downloadBtn">Download .txt</button>
        <button type="button" id="jsonBtn">Copy JSON</button>
      </div>
    </section>
  </main>
</div>

<div class="toast" id="toast">Copied</div>

<script>
(function(){
  "use strict";

  var fields = [
    "brand","product","category","keyword","audience","price",
    "features","claims","evidence","objections","tone","cta"
  ];

  var els = {};
  fields.forEach(function(id){ els[id] = document.getElementById(id); });

  var out = {
    previewBadge: document.getElementById("previewBadge"),
    previewTitle: document.getElementById("previewTitle"),
    previewDesc: document.getElementById("previewDesc"),
    previewBullets: document.getElementById("previewBullets"),
    previewPrice: document.getElementById("previewPrice"),
    previewProof: document.getElementById("previewProof"),
    previewCta: document.getElementById("previewCta"),
    warnings: document.getElementById("warnings"),
    shelfMeter: document.getElementById("shelfMeter"),
    proofMeter: document.getElementById("proofMeter"),
    riskMeter: document.getElementById("riskMeter"),
    shelfScore: document.getElementById("shelfScore"),
    proofScore: document.getElementById("proofScore"),
    riskScore: document.getElementById("riskScore"),
    seoTitle: document.getElementById("seoTitle"),
    seoTitleCount: document.getElementById("seoTitleCount"),
    seoH1: document.getElementById("seoH1"),
    seoH1Count: document.getElementById("seoH1Count"),
    seoMeta: document.getElementById("seoMeta"),
    seoMetaCount: document.getElementById("seoMetaCount"),
    serpTitle: document.getElementById("serpTitle"),
    serpUrl: document.getElementById("serpUrl"),
    serpMeta: document.getElementById("serpMeta"),
    exportText: document.getElementById("exportText"),
    toast: document.getElementById("toast")
  };

  var storageKey = "ecommerceShelfCardStressTest.v1";

  var riskyPatterns = [
    {re:/\bbest\b|\b#1\b|\bnumber one\b/i, name:"Superlative claim", fix:"Replace with a specific comparison or add credible third-party proof."},
    {re:/\bguaranteed\b|\bguarantee\b|\bnever\b|\balways\b/i, name:"Absolute promise", fix:"Soften the claim or add exact guarantee terms."},
    {re:/\bclinical\b|\bclinically\b|\bdoctor\b|\bdermatologist\b|\bmedical\b|\bheal\b|\bcure\b/i, name:"Health or clinical claim", fix:"Use only with qualified evidence and compliant wording."},
    {re:/\beco\b|\beco-friendly\b|\bsustainable\b|\bgreen\b|\bplanet\b|\bbiodegradable\b|\bcompostable\b/i, name:"Environmental claim", fix:"Name the material, certification, or measurable environmental basis."},
    {re:/\bwaterproof\b|\bleakproof\b|\bunbreakable\b|\bindestructible\b/i, name:"Durability claim", fix:"Add test conditions, limits, or use a softer phrase like leak-resistant."},
    {re:/\bhypoallergenic\b|\bnon-toxic\b|\borganic\b|\bnatural\b|\bchemical-free\b/i, name:"Material safety claim", fix:"Add certification, ingredient standard, or exact material basis."},
    {re:/\bfastest\b|\blightest\b|\bstrongest\b|\bultimate\b/i, name:"Extreme performance claim", fix:"Use a measurable spec or remove the unsupported comparison."}
  ];

  var weakWords = /\bpremium\b|\bquality\b|\bcomfortable\b|\bdurable\b|\bversatile\b|\bperfect\b|\bmodern\b|\bstylish\b|\binnovative\b/i;
  var proofWords = /\btested\b|\bcertified\b|\bcertification\b|\breview\b|\breviews\b|\brating\b|\bstudy\b|\blab\b|\bwarranty\b|\bmaterial\b|\bstandard\b|\bASTM\b|\bFDA\b|\bUL\b|\bOEKO\b|\bGOTS\b|\bUSDA\b|\bISO\b|\bBPA\b|\bstainless\b|\bcotton\b|\bpolyester\b|\bmeasurement\b|\bmeasured\b|\btrial\b|\bminutes\b|\bhours\b|\byears\b|\bpercent\b|%|\d/i;

  function clean(value){
    return String(value || "").replace(/\s+/g," ").trim();
  }

  function lines(value){
    return String(value || "")
      .split(/\n|;|\u2022/g)
      .map(clean)
      .filter(Boolean);
  }

  function clamp(n,min,max){
    return Math.max(min,Math.min(max,n));
  }

  function sentenceCase(s){
    s = clean(s);
    if(!s) return "";
    return s.charAt(0).toUpperCase() + s.slice(1);
  }

  function truncateWords(text, maxChars){
    text = clean(text);
    if(text.length <= maxChars) return text;
    var cut = text.slice(0, maxChars - 1);
    var last = cut.lastIndexOf(" ");
    if(last > 40) cut = cut.slice(0,last);
    return clean(cut) + "…";
  }

  function getState(){
    var state = {};
    fields.forEach(function(id){ state[id] = els[id].value; });
    return state;
  }

  function setState(state){
    fields.forEach(function(id){
      if(Object.prototype.hasOwnProperty.call(state,id)){
        els[id].value = state[id];
      }
    });
    update();
  }

  function save(){
    try{
      localStorage.setItem(storageKey, JSON.stringify(getState()));
    }catch(e){}
  }

  function load(){
    try{
      var raw = localStorage.getItem(storageKey);
      if(raw) setState(JSON.parse(raw));
      else update();
    }catch(e){
      update();
    }
  }

  function makeTitle(state){
    var brand = clean(state.brand);
    var product = clean(state.product);
    var category = clean(state.category);
    var keyword = clean(state.keyword);

    var base = product || keyword || category || "Product name";
    if(brand && product && product.toLowerCase().indexOf(brand.toLowerCase()) === -1){
      base = brand + " " + product;
    }
    return base;
  }

  function makeDescription(state, featureList, proofList){
    var product = makeTitle(state);
    var audience = clean(state.audience);
    var category = clean(state.category);
    var tone = state.tone;
    var feature = featureList[0] || category || "built for everyday use";
    var proof = proofList[0] || "";

    var opener = product;
    if(category) opener += " is a " + category;
    else opener += " is built for shoppers";

    if(audience) opener += " made for " + audience;
    opener += ".";

    var second = "It highlights " + feature;
    if(featureList[1]) second += ", " + featureList[1];
    if(proof && proofWords.test(proof)) second += ", with support from " + proof.toLowerCase();
    second += ".";

    if(tone === "premium") return opener + " Refined details and practical specs help it feel polished without hiding the facts. " + second;
    if(tone === "warm") return opener + " A useful, giftable choice with details shoppers can scan quickly. " + second;
    if(tone === "technical") return opener + " Specs, limits, and proof points stay close to the claim. " + second;
    if(tone === "minimal") return opener + " " + second;

    return opener + " " + second;
  }

  function buildBullets(featureList, proofList, objections){
    var bullets = featureList.slice(0,4);
    if(bullets.length < 3 && proofList.length){
      bullets.push("Proof point: " + proofList[0]);
    }
    if(bullets.length < 3 && objections.length){
      bullets.push("Best-fit note: " + objections[0]);
    }
    while(bullets.length < 3){
      bullets.push("Add a concrete feature or shopper benefit");
    }
    return bullets.slice(0,5);
  }

  function analyze(state){
    var featureList = lines(state.features);
    var claimList = lines(state.claims);
    var proofList = lines(state.evidence);
    var objectionList = lines(state.objections);
    var warnings = [];

    var hasProduct = !!clean(state.product);
    var hasKeyword = !!clean(state.keyword);
    var hasProof = proofList.join(" ").match(proofWords);
    var hasSpecs = featureList.join(" ").match(/\d|oz|inch|inches|cm|mm|lb|lbs|kg|hour|hours|watt|cotton|steel|wood|glass|ceramic|polyester|leather|capacity|size|weight/i);

    if(!hasProduct){
      warnings.push({
        level:"high",
        title:"Missing product name",
        copy:"The card cannot anchor the offer clearly without a product name."
      });
    }

    if(!featureList.length){
      warnings.push({
        level:"high",
        title:"No features or specs",
        copy:"Add concrete features, dimensions, materials, use cases, or compatibility details."
      });
    }

    if(featureList.length > 7){
      warnings.push({
        level:"med",
        title:"Too many shelf-card bullets",
        copy:"Keep the visible card to 3 to 5 bullets. Move the rest lower on the product page."
      });
    }

    if(!hasSpecs && featureList.length){
      warnings.push({
        level:"med",
        title:"Features look vague",
        copy:"Add measurable specs, materials, dimensions, capacity, compatibility, or test conditions."
      });
    }

    if(claimList.length && !proofList.length){
      warnings.push({
        level:"high",
        title:"Claims entered with no evidence",
        copy:"Add proof, soften the language, or remove claims that cannot be supported."
      });
    }

    claimList.forEach(function(claim){
      riskyPatterns.forEach(function(item){
        if(item.re.test(claim)){
          warnings.push({
            level: hasProof ? "med" : "high",
            title: item.name + ": “" + truncateWords(claim, 58) + "”",
            copy: item.fix
          });
        }
      });

      if(weakWords.test(claim) && !/\d|because|made with|tested|certified|rated|review/i.test(claim)){
        warnings.push({
          level:"low",
          title:"Vague value claim: “" + truncateWords(claim, 58) + "”",
          copy:"Convert the adjective into a visible reason to believe."
        });
      }
    });

    if(claimList.length > 6){
      warnings.push({
        level:"med",
        title:"Claim stack is getting heavy",
        copy:"A shelf card should sell one main promise, not force the shopper to process every possible angle."
      });
    }

    if(!hasKeyword){
      warnings.push({
        level:"low",
        title:"No target keyword",
        copy:"Add one primary search phrase so the title, H1, and meta can align."
      });
    }

    if(clean(state.price).length === 0){
      warnings.push({
        level:"low",
        title:"No price or offer note",
        copy:"Add price, shipping threshold, bundle, discount, or availability note if it affects conversion."
      });
    }

    var riskyCount = warnings.filter(function(w){ return w.level === "high"; }).length;
    var medCount = warnings.filter(function(w){ return w.level === "med"; }).length;
    var lowCount = warnings.filter(function(w){ return w.level === "low"; }).length;

    var shelfScore = 100;
    shelfScore -= hasProduct ? 0 : 20;
    shelfScore -= featureList.length ? 0 : 22;
    shelfScore -= hasSpecs ? 0 : 12;
    shelfScore -= claimList.length > 6 ? 8 : 0;
    shelfScore -= medCount * 5;
    shelfScore -= lowCount * 2;
    shelfScore = clamp(Math.round(shelfScore),0,100);

    var proofScore = 20;
    proofScore += proofList.length * 12;
    proofScore += hasProof ? 30 : 0;
    proofScore += hasSpecs ? 12 : 0;
    proofScore -= riskyCount * 10;
    proofScore = clamp(Math.round(proofScore),0,100);

    var riskScore = 100 - (riskyCount * 25 + medCount * 10 + lowCount * 4);
    riskScore = clamp(Math.round(riskScore),0,100);

    return {
      features:featureList,
      claims:claimList,
      proof:proofList,
      objections:objectionList,
      warnings:warnings,
      shelfScore:shelfScore,
      proofScore:proofScore,
      riskScore:riskScore
    };
  }

  function makeSeo(state, analysis){
    var brand = clean(state.brand);
    var product = clean(state.product) || "Product";
    var category = clean(state.category);
    var keyword = clean(state.keyword);
    var audience = clean(state.audience);
    var feature = analysis.features[0] || category || "Everyday Use";

    var titleParts = [];
    titleParts.push(product);
    if(keyword && product.toLowerCase().indexOf(keyword.toLowerCase()) === -1) titleParts.push(keyword);
    else if(category) titleParts.push(category);
    if(brand) titleParts.push(brand);

    var title = titleParts.filter(Boolean).join(" | ");
    if(title.length > 62){
      title = [product, keyword || category, brand].filter(Boolean).join(" - ");
    }
    title = truncateWords(title, 66);

    var h1 = product;
    if(category && product.toLowerCase().indexOf(category.toLowerCase()) === -1){
      h1 += " " + category;
    }

    var meta = "";
    if(keyword){
      meta += "Shop " + keyword;
    }else{
      meta += "Shop " + product;
    }
    if(brand) meta += " from " + brand;
    meta += " with " + feature.toLowerCase();
    if(audience) meta += " for " + audience;
    meta += ". Compare key specs, proof points, price notes, and fit before you buy.";
    meta = truncateWords(meta, 158);

    return {title:title,h1:h1,meta:meta};
  }

  function renderList(parent, items){
    while(parent.firstChild) parent.removeChild(parent.firstChild);
    items.forEach(function(item){
      var li = document.createElement("li");
      li.textContent = item;
      parent.appendChild(li);
    });
  }

  function renderWarnings(warnings){
    while(out.warnings.firstChild) out.warnings.removeChild(out.warnings.firstChild);

    if(!warnings.length){
      var empty = document.createElement("div");
      empty.className = "empty";
      empty.textContent = "No major warnings. The card still needs a human review, but the obvious claim, proof, and SEO problems are under control.";
      out.warnings.appendChild(empty);
      return;
    }

    warnings.forEach(function(w){
      var item = document.createElement("div");
      item.className = "warning " + w.level;

      var title = document.createElement("div");
      title.className = "warning-title";
      title.textContent = w.level.toUpperCase() + " · " + w.title;

      var copy = document.createElement("div");
      copy.className = "warning-copy";
      copy.textContent = w.copy;

      item.appendChild(title);
      item.appendChild(copy);
      out.warnings.appendChild(item);
    });
  }

  function setMeter(el, score, reverse){
    var pct = clamp(score,0,100);
    el.style.width = pct + "%";
    if(reverse){
      el.style.background = score >= 75 ? "var(--good)" : score >= 45 ? "var(--warn)" : "var(--bad)";
    }else{
      el.style.background = score >= 75 ? "var(--good)" : score >= 45 ? "var(--warn)" : "var(--bad)";
    }
  }

  function makeExport(state, analysis, seo){
    var title = makeTitle(state);
    var desc = makeDescription(state, analysis.features, analysis.proof);
    var bullets = buildBullets(analysis.features, analysis.proof, analysis.objections);

    var warningText = analysis.warnings.length
      ? analysis.warnings.map(function(w){ return "- [" + w.level.toUpperCase() + "] " + w.title + " — " + w.copy; }).join("\n")
      : "- No major warnings flagged.";

    return [
      "ECOMMERCE SHELF CARD COPY",
      "",
      "Product: " + title,
      "Category: " + (clean(state.category) || "Not set"),
      "Audience: " + (clean(state.audience) || "Not set"),
      "Price / offer: " + (clean(state.price) || "Not set"),
      "",
      "Short description:",
      desc,
      "",
      "Shelf bullets:",
      bullets.map(function(b){ return "- " + b; }).join("\n"),
      "",
      "CTA:",
      clean(state.cta) || "Add to cart",
      "",
      "SEO:",
      "Title: " + seo.title,
      "H1: " + seo.h1,
      "Meta: " + seo.meta,
      "",
      "Claim / evidence warnings:",
      warningText,
      "",
      "Proof points:",
      analysis.proof.length ? analysis.proof.map(function(p){ return "- " + p; }).join("\n") : "- Add evidence before publishing strong claims.",
      "",
      "Objection notes:",
      analysis.objections.length ? analysis.objections.map(function(o){ return "- " + o; }).join("\n") : "- None entered."
    ].join("\n");
  }

  function update(){
    var state = getState();
    var analysis = analyze(state);
    var seo = makeSeo(state, analysis);
    var title = makeTitle(state);
    var desc = makeDescription(state, analysis.features, analysis.proof);
    var bullets = buildBullets(analysis.features, analysis.proof, analysis.objections);

    out.previewBadge.textContent = clean(state.category) || clean(state.keyword) || "Category";
    out.previewTitle.textContent = title;
    out.previewDesc.textContent = desc;
    out.previewPrice.textContent = clean(state.price) || "Price / offer";
    out.previewProof.textContent = analysis.proof.length ? "Proof: " + truncateWords(analysis.proof[0], 44) : "Proof needed";
    out.previewCta.textContent = clean(state.cta) || "Add to cart";

    renderList(out.previewBullets, bullets);
    renderWarnings(analysis.warnings);

    setMeter(out.shelfMeter, analysis.shelfScore);
    setMeter(out.proofMeter, analysis.proofScore);
    setMeter(out.riskMeter, analysis.riskScore);

    out.shelfScore.textContent = analysis.shelfScore + " / 100";
    out.proofScore.textContent = analysis.proofScore + " / 100";
    out.riskScore.textContent = analysis.riskScore + " / 100 safe";

    out.seoTitle.textContent = seo.title;
    out.seoTitleCount.textContent = seo.title.length + " characters. Aim for roughly 45 to 60.";
    out.seoH1.textContent = seo.h1;
    out.seoH1Count.textContent = seo.h1.length + " characters. Keep it clear and product-led.";
    out.seoMeta.textContent = seo.meta;
    out.seoMetaCount.textContent = seo.meta.length + " characters. Aim for roughly 140 to 160.";

    out.serpTitle.textContent = seo.title;
    out.serpUrl.textContent = "example.com/products/" + (clean(state.product) || "product").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
    out.serpMeta.textContent = seo.meta;

    out.exportText.value = makeExport(state, analysis, seo);

    save();
  }

  function showToast(message){
    out.toast.textContent = message;
    out.toast.classList.add("show");
    window.setTimeout(function(){
      out.toast.classList.remove("show");
    },1300);
  }

  function copyText(text, message){
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(function(){
        showToast(message || "Copied");
      }).catch(function(){
        fallbackCopy(text, message);
      });
    }else{
      fallbackCopy(text, message);
    }
  }

  function fallbackCopy(text, message){
    var temp = document.createElement("textarea");
    temp.value = text;
    temp.setAttribute("readonly","");
    temp.style.position = "fixed";
    temp.style.left = "-9999px";
    document.body.appendChild(temp);
    temp.select();
    try{ document.execCommand("copy"); }catch(e){}
    document.body.removeChild(temp);
    showToast(message || "Copied");
  }

  function downloadText(filename, text){
    var blob = new Blob([text], {type:"text/plain;charset=utf-8"});
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast("Downloaded");
  }

